import{_ as i,o,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Cronologia e recupero","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/cronologia-recupero.md","filePath":"user-guide/cronologia-recupero.md"}'),r={name:"user-guide/cronologia-recupero.md"};function t(l,e,s,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="cronologia-e-recupero" tabindex="-1">Cronologia e recupero <a class="header-anchor" href="#cronologia-e-recupero" aria-label="Permalink to &quot;Cronologia e recupero&quot;">​</a></h1><p>Clarae notanda non perde silenziosamente i vostri dati: ogni versione scartata resta recuperabile, in due modi.</p><h2 id="versioni-locali-snapshot" tabindex="-1">Versioni locali (snapshot) <a class="header-anchor" href="#versioni-locali-snapshot" aria-label="Permalink to &quot;Versioni locali (snapshot)&quot;">​</a></h2><p>Mentre scrivete, l&#39;app crea <strong>snapshot</strong> automatici sul vostro dispositivo, nella cartella <code>.clarae/snapshots</code> del vault, senza duplicare contenuti identici. Si fanno anche <strong>prima di un ripristino</strong> e <strong>prima che la sincronizzazione sovrascriva</strong> una nota. In <em>Impostazioni → Recupero file</em> regolate l&#39;intervallo tra gli snapshot, per quanti giorni conservarli, la dimensione massima del singolo file e il limite totale di spazio.</p><h2 id="versioni-del-cloud" tabindex="-1">Versioni del cloud <a class="header-anchor" href="#versioni-del-cloud" aria-label="Permalink to &quot;Versioni del cloud&quot;">​</a></h2><p>Se il vault è sincronizzato, il server conserva le <strong>revisioni</strong> di ogni file (tutte per un certo numero di giorni, poi una al giorno, poi nulla: lo decide l&#39;amministratore). Lo storico non conta nella quota.</p><h2 id="ripristinare-una-versione" tabindex="-1">Ripristinare una versione <a class="header-anchor" href="#ripristinare-una-versione" aria-label="Permalink to &quot;Ripristinare una versione&quot;">​</a></h2><ol><li>Aprite la nota → <em>Recupero file per questa nota</em> (o <em>Cronologia versioni della nota</em>).</li><li>L&#39;elenco unisce le versioni del dispositivo e del cloud, con data e origine. Selezionandone una vedete il <strong>confronto</strong> con il testo attuale.</li><li><em>Ripristina questa versione</em>: la nota viene sostituita, ma <strong>il testo attuale viene salvato prima</strong>, quindi potete sempre tornare indietro.</li></ol><p>Nei vault condivisi in sola lettura potete vedere le versioni ma non ripristinarle.</p><h2 id="file-eliminati" tabindex="-1">File eliminati <a class="header-anchor" href="#file-eliminati" aria-label="Permalink to &quot;File eliminati&quot;">​</a></h2><p><em>Recupera file eliminati</em> elenca i file cancellati di cui esiste una versione salvata, con l&#39;ultima versione disponibile; <em>Ripristina file</em> lo ricrea. Le note eliminate vanno anche nel <strong>cestino</strong> (di sistema o del vault, a scelta in <em>Impostazioni → File e link</em>).</p><h2 id="conflitti-di-sincronizzazione" tabindex="-1">Conflitti di sincronizzazione <a class="header-anchor" href="#conflitti-di-sincronizzazione" aria-label="Permalink to &quot;Conflitti di sincronizzazione&quot;">​</a></h2><p>Le copie di conflitto e le versioni scartate dal merge restano nella cronologia: vedi <a href="./sync-cloud.html">Sincronizzazione e cloud</a>.</p>',13)])])}const h=i(r,[["render",t]]);export{m as __pageData,h as default};
